#!/usr/bin/env bash
# Arm the scheduler on evo-dev: cron installed and running, the MiHomes block in the crontab.
#
#   bash ~/MiHomes/scripts/ops/install-cron.sh          (as millena, not root)
#
# Idempotent — safe on every boot, which is where it belongs: evo-dev is a container with no
# systemd, and a rebuild drops the cron package and the daemon (2026-09-23, 2026-11-02). Call it
# from ~/.mihomes/run/boot.sh so a restart re-arms everything.
#
# The block is generated by `mihomes cron crontab` from cli/jobs.py::SCHEDULE, so it cannot
# drift from the manifest. Lines outside the BEGIN/END markers are kept.
set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

if [ "$(id -u)" = 0 ]; then
    echo "run as the app user (millena), not root — the crontab must be that user's" >&2
    exit 1
fi

if [ ! -x /usr/sbin/cron ]; then
    echo "installing cron…"
    sudo -n apt-get update -qq
    sudo -n env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq cron
fi

if ! pgrep -x cron > /dev/null; then
    echo "starting cron…"
    sudo -n /usr/sbin/cron
fi

load_env
runner="$MIHOMES_REPO/scripts/ops/run-job.sh"
backup="$MIHOMES_REPO/scripts/ops/pg-backup.sh"
keepalive="$MIHOMES_REPO/scripts/ops/keepalive.sh"
errfile="$(mktemp)"
trap 'rm -f "$errfile"' EXIT
if ! block="$(env -i "${E[@]}" "$MIHOMES_BIN" cron crontab --runner "$runner" --backup "$backup" --keepalive "$keepalive" 2> "$errfile")"; then
    echo "'mihomes cron crontab' failed — crontab left unchanged:" >&2
    echo "$block" >&2
    cat "$errfile" >&2
    exit 1
fi

case "$block" in
    "# BEGIN MiHomes"*"# END MiHomes") ;;
    *) echo "unexpected output from 'mihomes cron crontab' — crontab left unchanged:" >&2
       echo "$block" >&2
       exit 1 ;;
esac

current="$(crontab -l 2>/dev/null || true)"
others="$(printf '%s\n' "$current" | awk '
    /^# BEGIN MiHomes/ { skip = 1; next }
    /^# END MiHomes/   { skip = 0; next }
    !skip')"

{
    [ -n "$others" ] && printf '%s\n' "$others"
    printf '%s\n' "$block"
} | crontab -

echo "crontab installed ($(printf '%s\n' "$block" | grep -vc '^#') MiHomes line(s)):"
crontab -l
